192: let current: Settings = DEFAULTS;
193: let loaded = false;
194: const listeners = new Set<() => void>();
195: 
196: function apply(settings: Settings) {
197:   const root = document.documentElement;
198:   root.dataset.corners = settings.corners;
199:   for (const { vars } of Object.values(PALETTES)) {
200:     for (const name of Object.keys(vars)) root.style.removeProperty(name);
201:   }
202:   const palette = PALETTES[settings.palette];
203:   for (const [name, value] of Object.entries(palette.vars)) root.style.setProperty(name, value);
204:   root.style.setProperty("--accent-dark", palette.accentDark);
205:   root.style.setProperty("--ink-3", palette.ink3);
206:   root.style.setProperty("--tab-active", palette.tab);
207: }
208: 
209: function load() {
210:   if (loaded) return;
211:   loaded = true;
212:   try {
213:     const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "{}");
214:     current = {
215:       corners: saved.corners === "sharp" ? "sharp" : "rounded",
216:       palette: saved.palette in PALETTES ? saved.palette : DEFAULTS.palette,
217:       heat: saved.heat === "classic" ? "classic" : "fade",
218:       cost: saved.cost !== false,
219:     };
220:   } catch {
221:     current = DEFAULTS;
222:   }
223:   apply(current);
224: }
225: 
226: export function updateSettings(patch: Partial<Settings>) {
227:   load();
228:   current = { ...current, ...patch };
229:   localStorage.setItem(STORAGE_KEY, JSON.stringify(current));
230:   apply(current);
231:   listeners.forEach((l) => l());
232: }
233: 
234: function subscribe(listener: () => void) {
235:   load();
236:   listeners.add(listener);
237:   listener();
238:   return () => listeners.delete(listener);
239: }
240: 
241: export function useSettings(): Settings {
242:   return useSyncExternalStore(subscribe, () => current, () => DEFAULTS);
243: }

