46: function heatRamp(id: LayerId, layers: TractLayers | null, palette: Palette, style: HeatStyle): ExpressionSpecification {
47:   if (style === "classic") {
48:     // The earlier ramp: fixed score stops, so every tract is tinted by its score.
49:     return [
50:       "interpolate", ["linear"], ["get", id],
51:       0, `rgba(${rgb(palette.heat.mid)}, 0.1)`,
52:       0.5, `rgba(${rgb(palette.heat.mid)}, 0.45)`,
53:       1, `rgba(${rgb(palette.heat.hot)}, 0.75)`,
54:     ];
55:   }
56:   const values = Object.values(layers ?? {}).map((t) => t[id]);
57:   // Before any scores arrive there is nothing to rank, so nothing is painted.
58:   const sorted = (values.length ? values : [0, 1]).sort((a, b) => a - b);
59:   // Step stops must strictly rise, and a bunched layer repeats values.
60:   const breaks: number[] = [];
61:   for (const q of CLASS_PERCENTILES) {
62:     const v = quantile(sorted, q);
63:     breaks.push(breaks.length && v <= breaks[breaks.length - 1] ? breaks[breaks.length - 1] + 1e-6 : v);
64:   }
65:   return [
66:     "step", ["get", id], "rgba(0, 0, 0, 0)",
67:     breaks[0], palette.ramp[0],
68:     breaks[1], palette.ramp[1],
69:     breaks[2], palette.ramp[2],
70:     breaks[3], palette.ramp[3],
71:   ];
72: }
